def _security_upgrade() -> None:
    """Application role grants + tenant row-level security.

    The API connects as easyeap_app (not the table owner), so RLS always applies. A row is visible when its
    tenant_id equals the transaction's easyeap.tenant_id, or when the transaction explicitly enabled platform
    scope (easyeap.platform = 'on') for MSP-wide operations.
    """
    op.execute(
        "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'easyeap_app') "
        "THEN CREATE ROLE easyeap_app LOGIN; END IF; END $$"
    )
    op.execute("GRANT USAGE ON SCHEMA public TO easyeap_app")
    op.execute("GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO easyeap_app")
    op.execute("GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO easyeap_app")
    op.execute("REVOKE UPDATE, DELETE ON audit_events FROM easyeap_app")  # audit trail is append-only
    op.execute("REVOKE ALL ON alembic_version FROM easyeap_app")
    for table in TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} USING ("
            f"current_setting('easyeap.platform', true) = 'on' OR "
            f"tenant_id::text = current_setting('easyeap.tenant_id', true))"
        )
    # Association rows inherit tenant_id from their parent row (ORM secondary inserts only carry the two keys);
    # the RLS check still applies to the filled-in value.
    for table, parent, fk in (("access_rule_groups", "access_rules", "rule_id"), ("identity_groups", "identities", "identity_id")):
        op.execute(
            f"CREATE OR REPLACE FUNCTION easyeap_fill_{table}_tenant() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN "
            f"IF NEW.tenant_id IS NULL THEN SELECT tenant_id INTO NEW.tenant_id FROM {parent} WHERE id = NEW.{fk}; END IF; "
            f"RETURN NEW; END $$"
        )
        op.execute(f"CREATE TRIGGER fill_tenant BEFORE INSERT ON {table} FOR EACH ROW EXECUTE FUNCTION easyeap_fill_{table}_tenant()")
